  "upgrade.upgradeNeverRestartsTrial": "Баландбарӣ ҳеҷ гоҳ озмоиши ройгони шуморо аз нав оғоз намекунад.",
  "upgrade.trialHistoryNote": "Агар шумо барои Essentials пардохт кунед ва ба Business гузаред, шумо ҳамон ҳисоби муштарӣ ва таърихи озмоишро нигоҳ медоред. Business озмоиши ҳафтрӯзаи иловагиро дар бар намегирад. Агар шумо ҳангоми идома доштани озмоиши аслии худ баланд баред, санаи анҷоми аслии он аз нав муқаррар намешавад.",
  "upgrade.providerConfirmNote": "Тағйири нақша тасдиқи провайдери ҳисобдориро талаб мекунад. Ҳама гуна фарқияти нарх, таносуб ва санаи эътибор бояд пеш аз тасдиқи тағйирот нишон дода шавад. Баландбарӣ набояд обунаи дуюми ҳамзамонро эҷод кунад.",
  "upgrade.chargedThroughProviderNote": "Тағйири нақша тавассути провайдери ҳисобдорӣ ситонида мешавад. Шумо метавонед обунаи худро аз ин саҳифа бо истифода аз тугмаи Бекор кардани обуна дар зери нақшаи ҷории худ ё аз Танзимот бекор кунед. Бекор кардан навсозиҳои ояндаро дар анҷоми давраи пардохтшудаи шумо қатъ мекунад; он ҳеҷ гоҳ дастрасии шуморо якбора ба анҷом намерасонад. Фазоҳои кории ройгони мавҷуда бо дидани ин имконот ситонида намешаванд.",
  "billing.cancel.title": "Бекор кардани обуна",
  "billing.cancel.description": "Бекор кардани обуна аз {plan}. Бекор кардан навсозиҳои ояндаро дар анҷоми давраи пардохтшудаи шумо қатъ мекунад — он ҳеҷ гоҳ дастрасии шуморо якбора ба анҷом намерасонад.",
  "billing.cancel.yourPlan": "нақшаи шумо",
  "billing.cancel.doneTitle": "Обунаи шумо бекор карда шуд.",
  "billing.cancel.doneWithEnd": "Шумо дастрасии пурраро то {endDate} нигоҳ медоред. Пас аз он сана шумо давраи имтиёзи танҳо барои хондани {graceDays}-рӯза доред — шумо ҳанӯз метавонед ворид шавед ва маҳсулоти худро бинед, аммо наметавонед чизе илова, таҳрир, нест, скан, ворид, содир ё тағйир диҳед. {gracePart}",
  "billing.cancel.graceEndsOn": "Пас аз анҷоми давраи имтиёзи 15-рӯза {date}, ҳисоби шумо ва ҳамаи маълумоти он ба таври доимӣ нест карда мешавад ва онро барқарор кардан мумкин нест.",
  "billing.cancel.doneNoEnd": "Шумо дастрасии пурраро то анҷоми давраи пардохтшуда нигоҳ медоред. Пас аз он, давраи имтиёзи танҳо барои хондани 15-рӯза татбиқ мешавад. {wipeSentence}",
  "billing.cancel.refundWindowOpen": "Шумо дар давоми 3 рӯзи пардохти аввалини пардохтшуда бекор кардед, бинобар ин шумо метавонед барои баргардонидани он пардохти аввал ҳақдор бошед. Бекор кардан худаш баргардониданро намедиҳад — онро тавассути {contact} дархост кунед.",
  "billing.cancel.refundWindowClosed": "Бекор кардан худаш баргардониданро намедиҳад. Баргардониданҳо танҳо дар давоми 3 рӯзи пардохти аввалини бомуваффақияти пардохтшуда татбиқ мешаванд, ки тавассути {contact} дархост карда мешаванд.",
  "billing.cancel.notCanceledTitle": "Обунаи шумо бекор карда НАШУД.",
  "billing.cancel.contactCode": "Агар шумо бо {contact} тамос гиред, ин рамзро зикр кунед: {code}",
  "billing.cancel.alreadyCanceledTitle": "Ин обуна аллакай бекор карда шудааст.",
  "billing.cancel.alreadyCanceledWithEnd": "Он {date} ба анҷом мерасад. Шумо то он вақт дастрасии пурраро нигоҳ медоред. Пас аз он сана шумо давраи имтиёзи танҳо барои хондани {graceDays}-рӯза барои дидани маҳсулоти худ доред. {wipeSentence}",
  "billing.cancel.alreadyCanceledNoEnd": "Он дар анҷоми давраи ҷории пардохтшуда ба анҷом мерасад. Шумо то он вақт дастрасии пурраро нигоҳ медоред.",
  "billing.cancel.appStoreNote": "Агар шумо ҳеҷ гоҳ тавассути Google Play ё Apple App Store обуна шавед, шояд ба шумо лозим шавад, ки онро тавассути танзимоти обунаи он мағоза бекор кунед. Ин муколама наметавонад ҳисобдории мағозаи барномаро қатъ кунад. Нест кардани барнома ё нест кардани ҳисоби StockHaven-и шумо обунаи мағозаро бекор намекунад.",
  "billing.cancel.trialNote": "Бекор кардан дар давоми озмоиши шумо 7 рӯзи пурраи шуморо нигоҳ медорад — дастрасӣ {date} ба анҷом мерасад ва аз шумо ҳеҷ чиз ситонида намешавад.",
  "billing.cancel.trialNoteNoDate": "Бекор кардан дар давоми озмоиши шумо 7 рӯзи пурраи шуморо нигоҳ медорад ва аз шумо ҳеҷ чиз ситонида намешавад.",
