  "billing.cancel.keepAccessRest": "Бекор кардан танҳо навсозиҳои ояндаро қатъ мекунад — он ҳеҷ гоҳ дастрасии шуморо якбора ба анҷом намерасонад ва ҳеҷ моҳи ройгони иловагӣ илова карда намешавад.",
  "billing.cancel.gracePeriodTitle": "Пас аз он сана, давраи имтиёзи танҳо барои хондани {graceDays}-рӯза.",
  "billing.cancel.gracePeriodRest": "Шумо ҳанӯз метавонед ворид шавед ва маҳсулоти худро бинед, бинобар ин шумо метавонед он чиро, ки доштед, бубинед ва нависед. Ҳама чизи дигар баста аст: илова, таҳрир, нест кардан, скан кардан, воридот, содирот ё кӯчондан нест, танзимот нест, кормандон нестанд.",
