  "billing.cancelError.purchaseContractMismatch": "Сабти ҳисобдорӣ ба ин тиҷорат мувофиқат намекунад, бинобар ин мо наметавонем онро дар ин ҷо бекор кунем. Ҳеҷ чиз тағйир наёфт — лутфан бо дастгирӣ тамос гиред.",
