  "billing.cancelError.subscriptionPaidThroughUnverified": "Мо санаи пардохтшудаи шуморо тасдиқ карда натавонистем. Ҳеҷ чиз тағйир наёфт — лутфан аз нав кӯшиш кунед ё бо дастгирӣ тамос гиред.",
