  "billing.cancelError.subscriptionEventHistoryIncomplete": "Таърихи ҳисобдории шумо пеш аз бекор кардан ба баррасӣ ниёз дорад. Ҳеҷ чиз тағйир наёфт — лутфан бо дастгирӣ тамос гиред.",
  "billing.cancelError.eventRequiresReview": "Таърихи ҳисобдории шумо пеш аз бекор кардан ба баррасӣ ниёз дорад. Ҳеҷ чиз тағйир наёфт — лутфан бо дастгирӣ тамос гиред.",
  "billing.cancelError.subscriptionCancellationUnavailable": "Бекоркуниро анҷом додан мумкин нашуд. Ҳеҷ чиз тағйир наёфт — обуна ва дастрасии шумо маҳз ҳамон тавре ҳастанд, ки буданд. Лутфан аз нав кӯшиш кунед ё бо дастгирӣ тамос гиред.",
  "billing.readiness.ariaLabel": "Омодагии воқеии пардохти Essentials",
  "billing.readiness.title": "Пардохти Essentials — санҷиши воқеии бехатарии ҳисоб",
  "billing.readiness.body": "Сабтҳои воқеии обуна ва озмоишро бе харидани ҳеҷ чиз тафтиш кунед. Ҳисоби ройгони Business-и шумо ва намунаи пижамаи шумо бетағйир мемонанд. Ин пардохти Stripe-ро намекушояд, кортро ситонанда нест ё нақшаро тағйир намедиҳад.",
  "billing.readiness.checking": "Сабтҳои ҳисоб санҷида шуда истодаанд…",
  "billing.readiness.inspect": "Тафтиши омодагии пардохт (бе пардохт)",
  "billing.readiness.unknown": "Санҷиши танҳо барои хондан омодагиро муқаррар карда натавонист ({state}). Ҳеҷ чиз тағйир наёфт.",
  "billing.readiness.ready": "Пардохти Stripe омода аст — калидҳо, тасдиқи webhook ва шаҳодатҳо ҳама тасдиқ шудаанд.",
  "billing.readiness.complimentaryProtected": "Фазои кории ройгони Business-и шумо ҳифз шудааст. Он набояд ҳисоби озмоишии пардохтшудаи Essentials шавад.",
  "billing.readiness.environmentIncomplete": "Маълумоти пардохти Stripe, тасдиқи webhook ё суроғаи бозгашти барномаро ҳама тасдиқ кардан мумкин нашуд. Ҳеҷ пардохте оғоз шуда наметавонад.",
  "billing.readiness.ownerHasHistory": "Ин соҳиб далели обуна ё озмоиши қаблӣ дорад. Пардохти дуюм набояд эҷод карда шавад.",
  "billing.readiness.trialAlreadyUsed": "Озмоиши муқаддимавӣ аллакай истифода ё захира шудааст. Ҳеҷ озмоиши такрорӣ оғоз шуда наметавонад.",
  "billing.readiness.trialEligibilityUnverified": "Ҳаққонияти озмоиши якдафъаина барои ин соҳиб тасдиқ нашудааст. Пардохт баста мемонад.",
  "billing.readiness.testModeUnverified": "Сабтҳои ҳисоб хонда мешаванд, аммо нигоҳдории бехатари ҳолати озмоишии Stripe ва иҷрои навсозии пардохтшуда тасдиқ нашудаанд. Пардохт баста мемонад.",
  "billing.readiness.entitlementNotUnique": "Маълумоти нақшаи мавҷуда гум шудааст ё норавшан аст. Ҳеҷ пардохте оғоз шуда наметавонад.",
  "billing.readiness.accountBillingIncomplete": "Таърихи ҳисобдории ҳисобро пурра хондан мумкин нашуд. Ҳеҷ пардохте оғоз шуда наметавонад.",
  "billing.readiness.billingHistoryIncomplete": "Таърихи пурраи соҳибро тасдиқ кардан мумкин нашуд. Ҳеҷ пардохте оғоз шуда наметавонад.",
  "billing.readiness.ownershipMismatch": "Моликияти ҳисоб ё сабтҳои ҳисобдорӣ пеш аз оғози ҳама гуна обуна ба баррасӣ ниёз доранд.",
  "billing.readiness.catalogUnverified": "Таърифи пардохти серверии тасдиқшудаи $14.99/моҳ ба тасдиқ ниёз дорад.",
  "billing.readiness.auditUnavailable": "Санҷиши серверии танҳо барои хондан дастрас набуд. Ҳеҷ пардохт ё тағйири ҳисоб рух надод.",
  "billing.dryRun.ariaLabel": "Симулятсияи озмоишии баландбарӣ",
  "billing.dryRun.title": "Essentials → Business — симулятсияи машқӣ",
  "billing.dryRun.body": "Қоидаҳои баландбарии пешниҳодшударо бо истифода аз сабтҳои комилан афсонавӣ дар ин браузер машқ кунед. Ин TEST-и воқеии шуморо — намунаи шимҳои пижама, фазои кории ҷории Business-и шумо, Stripe, озмоишҳо, обунаҳо ё инвентарро намехонад ё тағйир намедиҳад.",
  "billing.dryRun.runButton": "Иҷрои симулятсияи маҳаллии баландбарӣ (бе пардохт)",
  "billing.dryRun.passed": "Сенарияи афсонавӣ аз санҷишҳои маҳаллии худ гузашт",
  "billing.dryRun.blocked": "Сенарияи афсонавӣ баста шуд",
  "billing.dryRun.example": "Мисол: Essentials ($14.99/моҳ) → Business ($29.99/моҳ), пеш аз ҳама гуна андози татбиқшаванда.",
  "billing.dryRun.preserved": "Ҳамон обуна нигоҳ дошта шуд, як озмоиши аслӣ нигоҳ дошта шуд ва инвентари пижамаи симулятсияшуда бетағйир монд. Муштарии мисолӣ дар Essentials мемонад, то навсозии воқеии пардохтшудаи аз ҷониби провайдер тасдиқшуда тағйири дастрасиро асоснок кунад.",
  "billing.dryRun.limitations": "Симулятсияи маҳаллӣ тағйири обунаи Stripe, пардохт, webhook, пешниҳоди нарх бо андоз, обунаи зинда ё сабтҳои воқеии тиҷорати шуморо санҷида наметавонад.",
  "billing.dryRun.noRecordsChanged": "Ҳеҷ сабте тағйир наёфт.",
