  "settings.separateDecisions": "Бекоркунии обуна ва нест кардани ҳисоб тасмимҳои ҷудогонаанд. Ҳеҷ обуна бекор карда намешавад ё ҳисоб бо дидани ин шартҳо нест карда намешавад.",
