  "settings.switcher.startsEmpty": "Инто холӣ оғоз мешавад ва фавран кушода мешавад.",
  "settings.switcher.taglineLabel": "Шиор",
  "settings.switcher.taglinePlaceholder": "Ихтиёрӣ",
  "settings.switcher.upgrade": "Баланд бардоштан",
  "settings.title": "Танзимот",
  "settings.trial.cancelKeeps": "Бекор кардан дар давоми озмоиши шумо 7 рӯзи пурраи шуморо нигоҳ медорад — дастрасӣ {date} ба анҷом мерасад ва аз шумо ҳеҷ чиз ситонида намешавад.",
  "staff.access.noSeatBody": "Ҳисоби шумо барои ин тиҷорат ҷойи корманд надорад, бинобар ин захираи он баста мемонад. Аз соҳиб пурсед, ки шуморо дар Кормандон ва нақшҳо илова кунад.",
  "staff.access.noSeatTitle": "Ин тиҷорат барои воридшавии шумо кушода нест",
  "staff.access.pendingBody": "Ин тиҷорат барои почтаи электронии шумо даъвате дорад, ки фаъол карда нашудааст. Аз соҳиб пурсед, ки ҳолати кормандии шуморо ба фаъол муқаррар кунад. Ҳеҷ чиз дар ин ҷо то он вақт намоён нест.",
  "staff.access.pendingTitle": "Даъвати шумо ҳанӯз фаъол нест",
  "staff.access.signOut": "Берун рафтан",
  "staff.access.suspendedBody": "Маъмур ин ҳисоби кормандиро барои тиҷорати фаъол боздоштааст. Аз онҳо пурсед, ки шуморо ба фаъол баргардонанд, сипас аз нав ворид шавед.",
  "staff.access.suspendedTitle": "Дастрасии шумо таваққуф шудааст",
  "staff.addFirst": "Илова кардани корманди аввал",
  "staff.addMember": "Илова кардани корманд",
  "staff.emptyBody": "Шахсро илова кунед, ба онҳо нақш ва иҷозатҳоеро, ки бо он мераванд, диҳед ва онҳо бо почтаи электронӣ даъват карда мешаванд, то ба ин тиҷорат ворид шаванд.",
  "staff.emptyTitle": "Ҳанӯз кормандон нестанд",
  "staff.eyebrow": "Даста",
  "staff.how.p1": "Ҳар узв нақш ва рӯйхати иҷозатҳои худро дорад, бинобар ин шумо метавонед аз нақш оғоз кунед ва як чизро бе сохтани нақши нав тағйир диҳед. Таҳрири нақш аъзоҳоеро, ки аллакай дар он ҳастанд, аз нав наменависад — узвро кушоед, то пешфарзҳои нақши онҳоро аз нав татбиқ кунед.",
  "staff.how.p2": "Нақшҳои фармоишӣ хусусияти Business мебошанд: Essentials панҷ нақши дарунсохтро истифода мебарад (Соҳиб, Мудир, Корманди захира, Корманди фурӯш, Томошабин).",
  "staff.how.p3": "Даъватҳо бо почтаи электронӣ фиристода мешаванд. Узв танҳо вақте метавонад ворид шавад, ки қабул кунад ва тоза кардани касе аз ин рӯйхат ҳисоби барномаи онҳоро нест намекунад.",
  "staff.how.p4": "Мағоза маконе аст, ки шахс ба он таъин карда шудааст. Он дар корти онҳо сабт карда мешавад; он чи онҳо метавонанд кушоянд, ҳанӯз аз рӯи нақш ва иҷозатҳои онҳо тасмим гирифта мешавад.",
  "staff.how.p5": "Иҷозатҳо тасмим мегиранд, ки ҳар шахс чиро кушода метавонад: ашёҳои меню берун аз нақши онҳо пинҳон карда мешаванд ва суроғаи басташуда ба ҷои саҳифа огоҳии “дар нақши шумо нест”-ро нишон медиҳад. Тағйирот дафъаи дигар, ки он шахс барномаро бор мекунад, татбиқ мешавад; боздоштани узв онҳоро комилан қулф мекунад.",
  "staff.how.p6": "Маъмурон метавонанд ҳамаи маълумотро бубинанд ва тағйир диҳанд, корбарон ва нақшҳои барномаро идора кунанд ва ҳеҷ гоҳ аз ҷониби нақши кормандон маҳдуд карда намешаванд. Касе, ки сабти корманд надорад — соҳиби тиҷорати нав — дастрасии пурраро нигоҳ медорад.",
  "staff.howTitle": "Кормандон ва нақшҳо чӣ тавр кор мекунанд",
  "staff.limitBadgeLabel": "Кормандон",
  "staff.loading": "Кормандон бор шуда истодаанд…",
  "staff.member.administrator": "Маъмур",
  "staff.member.areas": " · {areas}",
  "staff.member.edit": "Таҳрир",
  "staff.member.inviteFailed": "Даъватро фиристодан мумкин нашуд",
