  "payroll.dd.steps.body": "1. Ба шумо суратҳисоби бонкии тиҷоратӣ лозим аст, ки пардохтҳои ACH-ро фиристода метавонад. 2. Аз ҳар як узви даста шакли иҷозати имзошударо ҷамъ кунед — чеки бекоршуда барои санҷиши рақамҳо кӯмак мекунад. 3. Музди меҳнатро 2-3 рӯзи корӣ пеш аз рӯзи пардохт фиристед, то пул сари вақт расад. 4. Аксари иёлотҳо розигии хаттии узви дастаро талаб мекунанд. Ин барнома шаклҳоро ҷамъ мекунад ва шуморо қадам ба қадам роҳнамоӣ мекунад — фиристодани воқеии пул тавассути бонки худи шумо анҷом мешавад.",
