  "workforce.unscheduledNote": "Имрӯз навбат ба нақша гирифта нашудааст, бинобар ин ин вақт берун аз ҷадвал қайд мешавад.",
  "workforce.inbox.help": "Рӯйдодҳои қайди вақт, ҷавобҳо ба рухсатӣ, вазифаҳо, варақаҳои музди меҳнат ва тағйироти ҷадвал барои дастаи шумо, аввал навтаринҳо.",
