  "training.newForYouHelp": "Ин дарсҳо илова карда шуданд, зеро нақши шумо афзуд ё касе онҳоро ба шумо таъин кард. Онҳоро ба итмом расонед, то қисмҳои нави барномаро омӯзед.",
