  "rewards.subtitle": "Бо мукофот ташаккур гӯед — фоизи тахфиф, корти тӯҳфа ё ҳар чизе, ки шумо тавсиф мекунед.",
  "rewards.title": "Мукофотҳо ва ҳавасмандгардониҳо",
  "rewards.value.giftCard": "Корти тӯҳфаи {value}",
  "rewards.value.percentOff": "{percent}% тахфиф дар мағоза",
  "rewards.void": "Бекор кардан",
  "rewards.voided": "Мукофот бекор карда шуд.",
  "workforce.tab.rewards": "Мукофотҳо",
  "training.lessons.mgr-give-rewards.step1": "Дастаро кушоед ва Мукофотҳоро зер кунед. Узви дастаро интихоб кунед, сипас навъро: фоизи тахфиф дар мағоза, корти тӯҳфа ё чизи дигаре, ки шумо бо калимаҳои худ тавсиф мекунед.",
  "training.lessons.mgr-give-rewards.step2": "Ба мукофот номи кӯтоҳ ва агар хоҳед, қайд диҳед. Шахс дарҳол зангӯла мегирад ва мукофот дар Мукофотҳои ман-и онҳо бо рамзи худ интизор аст.",
  "training.lessons.mgr-give-rewards.step3": "Сарҳад, аз рӯи тарҳ: шумо танҳо КОРМАНДОНРО мукофот медиҳед. Шумо худ ё менеҷери дигарро мукофот дода наметавонед — мукофот додани менеҷер кори соҳиб аст ва барнома онро равшан рад мекунад.",
  "training.lessons.mgr-give-rewards.step4": "Дар хазина рамзеро, ки узви даста ба шумо нишон медиҳад, нависед ва онро ҳамчун истифодашуда қайд кунед — ҳар як рамз як маротиба кор мекунад. Шумо мукофотеро, ки додаед, агар нақшаҳо тағйир ёбанд, бекор карда метавонед; тӯҳфаҳои соҳиб аз они соҳибанд, ки бекор кунад.",
  "training.lessons.mgr-give-rewards.title": "Додани мукофотҳо ба кормандони шумо",
  "training.lessons.owner-give-rewards.step1": "Мукофотҳо дар Даста, дар ҷадвали Мукофотҳо зиндагӣ мекунанд ва онҳо танҳо барои нақшаи Business мебошанд — дар Essentials ҷадвал дари қулфшударо нишон медиҳад, то дастаи шумо бубинад, ки нақшаи калонтар чӣ дорад.",
  "training.lessons.owner-give-rewards.step2": "Шумо метавонед ҲАР КАСО дар даста мукофот диҳед — кормандон ва менеҷерон яксон. Шахсро интихоб кунед, сипас навъро: фоизи тахфиф дар мағоза (ҳама гуна фоизе, ки шумо интихоб мекунед), корти тӯҳфа ба ҳар ҷо ё ҳама гуна ҳавасмандгардоние, ки шумо бо калимаҳои худ тавсиф мекунед.",
  "training.lessons.owner-give-rewards.step3": "Мукофот бо рамзи якдафъаинаи худ меояд ва зангӯлаи шахсро мезанад. Онҳо рамзро дар хазина нишон медиҳанд; соҳиб ё менеҷер онро барои ҳамчун истифодашуда қайд кардан менависад.",
  "training.lessons.owner-give-rewards.step4": "Варақаи мукофоти чопшуда ё мубодилашуда танҳо номи тиҷорати ШУМО-ро дорад — ҳеҷ гоҳ номи барномаро не. Ин ташаккури мағозаи шумост, на таблиғ.",
  "training.lessons.owner-give-rewards.title": "Додани мукофотҳо (нақшаи Business)",
  "training.lessons.owner-rewards-oversight.step1": "Менеҷери шумо низ мукофот дода метавонад — танҳо ба кормандон. Барнома менеҷерро, ки худ ё менеҷери дигарро мукофот медиҳад, рад мекунад; мукофот додани менеҷер ҳамеша кори шумост.",
  "training.lessons.owner-rewards-oversight.step2": "Шумо ҳар як мукофотро дар тиҷорат дар Таърихи мукофотҳо мебинед: кӣ онро дод, кӣ онро гирифт ва оё он омода, истифодашуда ё бекоршуда аст. Менеҷер танҳо мукофотҳоеро мебинад, ки онҳо додаанд ва онҳоеро, ки гирифтаанд.",
  "training.lessons.owner-rewards-oversight.step3": "Шумо ҳама гуна мукофотро, аз ҷумла яктоашро, ки менеҷери шумо додааст, бекор карда метавонед. Менеҷер тӯҳфаҳои худро бекор карда метавонад, аммо ҳеҷ гоҳ тӯҳфаҳои шуморо не.",
  "training.lessons.owner-rewards-oversight.step4": "Ҳар як рамз дақиқан як маротиба кор мекунад ва мукофоти бекоршуда ҳеҷ гоҳ истифода шуда наметавонад — таърих ҳамеша нишон медиҳад, ки мукофот чӣ гуна ба охир расид.",
  "training.lessons.owner-rewards-oversight.title": "Назорати мукофотҳо: додани менеҷери шумо",
  "training.lessons.staff-your-rewards.step1": "Вақте ки менеҷери шумо ё соҳиб ба шумо мукофот медиҳад, зангӯлаи шумо садо медиҳад. Дастаро кушоед ва Мукофотҳоро зер кунед, то онро дар зери Мукофотҳои ман бубинед.",
  "training.lessons.staff-your-rewards.step2": "Ҳар як мукофот рамзи худро дорад. Онро барои худ нигоҳ доред — касе, ки рамзро дар хазина нишон медиҳад, ҳамон касест, ки мукофотро истифода мебарад.",
  "training.lessons.staff-your-rewards.step3": "Барои истифодаи он, вақте ки шумо мехаред, рамзро нишон диҳед. Шахс дар хазина онро менависад ва ҳамчун истифодашуда қайд мекунад — ҳар як рамз дақиқан як маротиба кор мекунад.",
  "training.lessons.staff-your-rewards.step4": "Мукофотҳо лаззати нақшаи Business мебошанд. Агар мағозаи шумо дар Business набошад, ҷадвали Мукофотҳо ба ҷои он дари қулфшударо нишон медиҳад — ин нақша аст, на хатогӣ.",
  "training.lessons.staff-your-rewards.title": "Мукофотҳои шумо: ёфтани рамзи шумо ва истифодаи он",
  "training.module.rewards": "Мукофотҳо ва ҳавасмандгардониҳо",
