  "pos.events.heldPlanNote": "Баъзе фурӯшҳои поён вақте омаданд, ки ин мағоза дар нақшаи Business набуд. Онҳо бехатар нигоҳ дошта шуданд ва ҳеҷ чиз ҳисоб нашуд. Ҳоло, ки мағоза дар Business аст, шумо онҳоро ҳисоб карда метавонед.",
